// Package migrations embeds the versioned SQL migrations, one directory per dialect.
//
// Files are generated by `go run ./internal/tools/migdiff` from ent/schema (Atlas diff,
// goose format) and must be committed. Never edit an applied migration; add a new one.
package migrations

import (
	"embed"
	"fmt"
	"io/fs"
)

//go:embed sqlite/*.sql mysql/*.sql postgres/*.sql
var all embed.FS

// FS returns the migration directory for a dialect ("sqlite", "mysql" or "postgres").
func FS(dialect string) (fs.FS, error) {
	switch dialect {
	case "sqlite", "mysql", "postgres":
		return fs.Sub(all, dialect)
	default:
		return nil, fmt.Errorf("no migrations for dialect %q", dialect)
	}
}
